import{_ as t,o as a,c as n,a2 as s}from"./chunks/framework.CDU0sSpB.js";const u=JSON.parse('{"title":"Multi-device and Long-running Operation","description":"How Hearth keeps tasks, authority, and data consistent across devices over time and handles backup, recovery, revocation, and upgrades.","frontmatter":{"title":"Multi-device and Long-running Operation","description":"How Hearth keeps tasks, authority, and data consistent across devices over time and handles backup, recovery, revocation, and upgrades.","outline":false},"headers":[],"relativePath":"en/design/operations.md","filePath":"en/design/operations.md","lastUpdated":null}'),i={name:"en/design/operations.md"};function o(r,e,d,c,l,p){return a(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="multi-device-and-long-running-operation" tabindex="-1">Multi-device and Long-running Operation <a class="header-anchor" href="#multi-device-and-long-running-operation" aria-label="Permalink to &quot;Multi-device and Long-running Operation&quot;">​</a></h1><p class="lead">Multi-device does not mean opening the same web page in several places. It means letting a computer, phone, and other trusted devices work with one logical assistant while handling offline use, synchronization, revocation, backup, and long-term state drift.</p><h2 id="design-goals" tabindex="-1">Design Goals <a class="header-anchor" href="#design-goals" aria-label="Permalink to &quot;Design Goals&quot;">​</a></h2><p>Users should see the same tasks, approvals, and artifacts on different devices and continue from where they stopped when switching devices. Devices can have different capabilities: a phone is better for approvals and takeover, a desktop can operate local software, and a home server can stay online. The system cannot assume every device is equal.</p><p>Offline is a normal state. A disconnected device can still inspect existing tasks, record actions, and queue pending actions. When it reconnects, actions are submitted in order. A conflict preserves both sources and asks for confirmation; it is never silently overwritten. When a device is lost or revoked, other devices stop sending it sensitive data and withdraw capability and keys as soon as possible.</p><p>Long-running operation is about resources, not merely &quot;it did not crash&quot;. Memory, disk, caches, logs, background tasks, connections, and temporary files need limits and cleanup rules. Health checks, anomaly alerts, upgrades, and rollback cover the service, database, device agents, and external connections.</p><p>Backup, recovery, and migration must be tested on real data. Users can export tasks, artifacts, memory, and necessary configuration, restore them on another device, and confirm that sensitive data, authority, and deletion state remain correct. Version upgrades keep old data readable, and a failed migration can roll back.</p><h2 id="design-tradeoffs" tabindex="-1">Design Tradeoffs <a class="header-anchor" href="#design-tradeoffs" aria-label="Permalink to &quot;Design Tradeoffs&quot;">​</a></h2><p>Hearth keeps one logical authoritative state while devices hold local projections and necessary offline queues. The user experiences one assistant, not several robots that disagree. Sync uses versions and deletion markers so an old device cannot resurrect content that was deleted.</p><table tabindex="0"><thead><tr><th>Scenario</th><th>Hearth&#39;s handling</th><th>What must not happen</th></tr></thead><tbody><tr><td>Switching devices</td><td>Rebuild tasks and artifacts from the shared record and keep the last position</td><td>Treating one device&#39;s temporary interface state as fact</td></tr><tr><td>Offline action</td><td>Queue locally, submit in order after reconnect, and validate versions</td><td>Silently choosing one side of a conflict</td></tr><tr><td>Device revocation</td><td>Withdraw capability, stop sync, rotate keys, and clear sensitive copies</td><td>Assuming a lost device will leave on its own</td></tr><tr><td>Backup and restore</td><td>Export with encryption and verify tasks, artifacts, memory, and authority</td><td>Backing up only the database while ignoring files and configuration</td></tr><tr><td>Version upgrade</td><td>Back up before migration and verify and support rollback afterward</td><td>Changing data structures when rollback is impossible</td></tr><tr><td>Long-running operation</td><td>Resource limits, health checks, cleanup, and anomaly alerts</td><td>Using &quot;just restart it&quot; to hide a leak or persistent drift</td></tr></tbody></table><p>Devices are capability and trust boundaries, not just login terminals. Pairing declares what a device can do, which data it can access, and whether local confirmation is required. High-risk capability is available only on explicitly authorized devices. Tasks can queue while a device is offline, but work involving a real-time external action pauses or asks for help.</p><p>Long-running tests last for weeks and observe memory, disk, task state, sync delay, permission drift, and external connections. If authority expands, state fails to converge, deleted content reappears, or external effects repeat, release stops and returns to the last stable version instead of adding more features.</p><p>The v1.0 standard is that a user can install, use, back up, migrate, and leave independently. The system does not need to cover every enterprise scenario, but a personal user must know where data lives, which devices are still valid, how to revoke authority, how to recover failed work, and how to continue without depending on the developers.</p>',13)])])}const v=t(i,[["render",o]]);export{u as __pageData,v as default};
